.dataframe > tbody > tr {
  text-align: right;
  white-space: pre-wrap;
}
</style>
<small>shape: (2, 6)</small><table border="1" class="dataframe"><thead><tr><th>native_1</th><th>native_2</th><th>native_3</th><th>udf_1</th><th>udf_2</th><th>udf_3</th></tr><tr><td>i64</td><td>i64</td><td>i64</td><td>i64</td><td>i64</td><td>i64</td></tr></thead><tbody><tr><td>1</td><td>2</td><td>3</td><td>3</td><td>3</td><td>3</td></tr><tr><td>2</td><td>4</td><td>6</td><td>6</td><td>6</td><td>6</td></tr></tbody></table></div>
```
